/* From Uiverse.io by aguerquin  - Tags: button, hover, cube, github, btn, hover button, 3d button, button hover effect  */
.__UIV_SCOPE__ .button-icon {
  display: flex;
  border: 3px #fff solid;
  width: fit-content;
  height: fit-content;
  cursor: pointer;
}

.__UIV_SCOPE__ .icon {
  background-color: #fff;
  padding: 10px 10px 5px 10px;
}

.__UIV_SCOPE__ .icon svg {
  width: 25px;
  height: 25px;
}

.__UIV_SCOPE__ .cube {
  transition: all 0.4s;
  transform-style: preserve-3d;
  width: 200px;
  height: 20px;
}

.__UIV_SCOPE__ .button-icon:hover {
  border-color: #ff98a2;
}

.__UIV_SCOPE__ .button-icon:hover .cube {
  transform: rotateX(90deg);
}

.__UIV_SCOPE__ .side {
  position: absolute;
  height: 47px;
  width: 200px;
  display: flex;
  font-size: 0.8em;
  justify-content: center;
  align-items: center;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  font-weight: bold;
}

.__UIV_SCOPE__ .top {
  background: #ff98a2;
  color: #fff;
  transform: rotateX(-90deg) translate3d(0, 13.5px, 2em);
}

.__UIV_SCOPE__ .front {
  background: #222229;
  color: #fff;
  transform: translate3d(0, 0, 1em);
}
